INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1033501040, /*drama_id*/1033501, /*command_type*/11, /*param_01*/'103311', /*param_02*/'突然说要牛奶和鸡蛋，\n我还以为出了什么事呢，没想到\n你居然为我准备了\n这么豪华的蛋糕！', /*param_03*/'6', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
