INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1033501043, /*drama_id*/1033501, /*command_type*/11, /*param_01*/'103311', /*param_02*/'我培育的食材加上小哥你的厨艺……\n这可以算是我们共同合作的结晶了……\n我、我什么都没说！\n你不用在意！', /*param_03*/'5', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
