INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1051501040, /*drama_id*/1051501, /*command_type*/11, /*param_01*/'105111', /*param_02*/'谢谢你为我庆祝生日。\n不管到了多少岁，\n得到别人的祝福都很让人开心呢。', /*param_03*/'7', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
