INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1051501043, /*drama_id*/1051501, /*command_type*/11, /*param_01*/'105111', /*param_02*/'诶，这蛋糕是你亲手做的？\n什么呀，这么体贴。', /*param_03*/'4', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
