INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1051501046, /*drama_id*/1051501, /*command_type*/11, /*param_01*/'105111', /*param_02*/'既然你准备得这么周到，\n那我也只好坦诚接受你的祝福了。\n就算是我，\n也能分清时间和场合哦。', /*param_03*/'6', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
