INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1051501049, /*drama_id*/1051501, /*command_type*/11, /*param_01*/'105111', /*param_02*/'不过，总是接受别人的好意\n不符合我的个性，下次\n我会送你强身健体的药\n作为谢礼的。', /*param_03*/'6', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
