INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1052501040, /*drama_id*/1052501, /*command_type*/11, /*param_01*/'105211', /*param_02*/'谢谢你送我这么漂亮的蛋糕！\n没想到\n会有人\n这么隆重地为我庆祝！', /*param_03*/'6', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1052501041, /*drama_id*/1052501, /*command_type*/91, /*param_01*/'0', /*param_02*/'', /*param_03*/'', /*param_04*/'', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1052501042, /*drama_id*/1052501, /*command_type*/21, /*param_01*/'vo_adv_1052501', /*param_02*/'vo_adv_1052501_001', /*param_03*/'0', /*param_04*/'0', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1052501043, /*drama_id*/1052501, /*command_type*/11, /*param_01*/'105211', /*param_02*/'能得到祝福就已经让我很开心了，\n竟然还送我亲手做的蛋糕……\n我总是接受你的好意，\n得到了很多东西呢。', /*param_03*/'6', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1052501044, /*drama_id*/1052501, /*command_type*/91, /*param_01*/'0', /*param_02*/'', /*param_03*/'', /*param_04*/'', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1052501045, /*drama_id*/1052501, /*command_type*/21, /*param_01*/'vo_adv_1052501', /*param_02*/'vo_adv_1052501_002', /*param_03*/'0', /*param_04*/'0', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1052501046, /*drama_id*/1052501, /*command_type*/11, /*param_01*/'105211', /*param_02*/'要是多少能回报你就好了……\n你有什么事情需要我做的吗？\n诶？　因为今天是我的生日，\n如果我过得开心，你就很高兴？', /*param_03*/'5', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1052501047, /*drama_id*/1052501, /*command_type*/91, /*param_01*/'0', /*param_02*/'', /*param_03*/'', /*param_04*/'', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1052501048, /*drama_id*/1052501, /*command_type*/21, /*param_01*/'vo_adv_1052501', /*param_02*/'vo_adv_1052501_003', /*param_03*/'0', /*param_04*/'0', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1052501049, /*drama_id*/1052501, /*command_type*/11, /*param_01*/'105211', /*param_02*/'我也非常开心哦！\n不过，听到你这么说，\n我就有点\n想任性一下了。', /*param_03*/'5', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1052501050, /*drama_id*/1052501, /*command_type*/91, /*param_01*/'0', /*param_02*/'', /*param_03*/'', /*param_04*/'', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
