INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1070501040, /*drama_id*/1070501, /*command_type*/11, /*param_01*/'107011', /*param_02*/'嗯，做得很不错啊。\n不忘值得尊敬的人，铭记恩情，\n举办庆贺健康的宴会……\n我很喜欢遵守礼仪的人哦。', /*param_03*/'4', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
