INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1070501043, /*drama_id*/1070501, /*command_type*/11, /*param_01*/'107011', /*param_02*/'但是，曾经\n如同婴孩一般的你\n竟然成长到现在的模样了……\n真是让人欣喜。', /*param_03*/'5', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
