INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1070501046, /*drama_id*/1070501, /*command_type*/11, /*param_01*/'107011', /*param_02*/'只不过，嗯……\n仅仅接受好意，\n并不符合我的性格。\n给你点奖励好了。', /*param_03*/'5', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
