INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1110501040, /*drama_id*/1110501, /*command_type*/11, /*param_01*/'111011', /*param_02*/'哇啊啊啊啊啊啊，这蜡烛是怎么回事！？\n在求知欲的驱使下忍不住吹灭了，\n这可疑的香味真让人感兴趣！\n知识通过鼻腔进入体内了！', /*param_03*/'5', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1110501041, /*drama_id*/1110501, /*command_type*/91, /*param_01*/'0', /*param_02*/'', /*param_03*/'', /*param_04*/'', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1110501042, /*drama_id*/1110501, /*command_type*/21, /*param_01*/'vo_adv_1110501', /*param_02*/'vo_adv_1110501_001', /*param_03*/'0', /*param_04*/'0', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1110501043, /*drama_id*/1110501, /*command_type*/11, /*param_01*/'111011', /*param_02*/'这个蜡烛难道是你做的吗？\n什么，精油里含有那么稀有的成分吗？\n是特意为了给我庆祝生日？\n后辈……你真是！', /*param_03*/'4', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1110501044, /*drama_id*/1110501, /*command_type*/91, /*param_01*/'0', /*param_02*/'', /*param_03*/'', /*param_04*/'', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1110501045, /*drama_id*/1110501, /*command_type*/21, /*param_01*/'vo_adv_1110501', /*param_02*/'vo_adv_1110501_002', /*param_03*/'0', /*param_04*/'0', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1110501046, /*drama_id*/1110501, /*command_type*/11, /*param_01*/'111011', /*param_02*/'虽说蜡烛很好，但这底座的部分——\n不，是名为生日蛋糕的祝福\n文化吗。嗯，谢谢你的好意，\n但是对于食量小的人来说，这个尺寸有点近似于拷问了……', /*param_03*/'4', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1110501047, /*drama_id*/1110501, /*command_type*/91, /*param_01*/'0', /*param_02*/'', /*param_03*/'', /*param_04*/'', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1110501048, /*drama_id*/1110501, /*command_type*/21, /*param_01*/'vo_adv_1110501', /*param_02*/'vo_adv_1110501_003', /*param_03*/'0', /*param_04*/'0', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1110501049, /*drama_id*/1110501, /*command_type*/11, /*param_01*/'111011', /*param_02*/'哎呀？　仔细一看这个底座的部分，\n蛋糕只占了一小部分，\n大半部分都是精致的模型啊！\n考、考虑得真周到！', /*param_03*/'5', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1110501050, /*drama_id*/1110501, /*command_type*/91, /*param_01*/'0', /*param_02*/'', /*param_03*/'', /*param_04*/'', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
