INSERT INTO `birthday_login_bonus_drama_script` VALUES (/*command_id*/1110501052, /*drama_id*/1110501, /*command_type*/11, /*param_01*/'111011', /*param_02*/'真没办法。\n直截了当地说，前辈有点感动。\n今晚喝酒唱歌，大闹一场吧。\n一起舞动到天明，同志，呀哈！', /*param_03*/'5', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'');
